//! The take-able containers of Crimson Desert build 26480954, by gimmick key.
//!
//! Generated by crates/tools/src/bin/gen-containers.rs (`just gen-containers`)
//! from the game's own archive tables: gimmickinfo (each record walked from
//! its key through its tags) and interactioninfo (`checkLootableField`). Do
//! not edit by hand; rerun `just gen-containers`.
//!
//! The rule, `analysis/container_catalog.py`'s for these two classes: a
//! record with a take interaction (`checkLootableField` 1 and named
//! `Gimmick_PickUp*`, `ItemHot_Collect*`, `ItemCold_Collect*`,
//! `Item_Collect_Reward*`, `Ship_PickUp*` or `ReadMemory_Paper_Collect*`)
//! that is not a puzzle box, a puzzle-box part, a chest, furniture storage
//! or personal storage is a `FurnitureDrop` when it carries the tag
//! `furniture_drop` and an `ItemContainer` when it carries
//! `catch_itemcontainer`. Every other record is absent: chests, breakable
//! containers, furniture doors and the player's own storage are not here.

/// What kind of take-able container a gimmick record is.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum ContainerClass {
    /// A self-contained basket, sack, crate, potion or donation box
    /// (`catch_itemcontainer`), taken whole; its own drop list is the
    /// contents.
    ItemContainer,
    /// A take-able box or bundle furniture hands out (`furniture_drop`),
    /// whose drop list is a room table.
    FurnitureDrop,
}

impl ContainerClass {
    /// The word the log lines use.
    pub fn name(self) -> &'static str {
        match self {
            ContainerClass::ItemContainer => "item-container",
            ContainerClass::FurnitureDrop => "furniture-drop",
        }
    }
}

