/// The class of the gimmickinfo record keyed `key`, `None` when it is not a
/// take-able container.
pub fn container_class(key: u32) -> Option<ContainerClass> {
    CONTAINERS
        .binary_search_by(|(k, _)| k.cmp(&key))
        .ok()
        .and_then(|i| CONTAINERS.get(i))
        .map(|&(_, c)| c)
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn sorted_and_unique() {
        assert!(CONTAINERS.windows(2).all(|w| w[0].0 < w[1].0));
    }

    fn count(c: ContainerClass) -> usize {
        CONTAINERS.iter().filter(|(_, x)| *x == c).count()
    }

    /// The counts on build 26480954.
    #[test]
    fn pinned_counts() {
        assert_eq!(count(ContainerClass::ItemContainer), 59);
        assert_eq!(count(ContainerClass::FurnitureDrop), 12);
    }

    #[test]
    fn spot_checks() {
        assert_eq!(container_class(1005717), Some(ContainerClass::ItemContainer)); // gimmick_box_donation_reward_coin_01
        assert_eq!(container_class(1004116), Some(ContainerClass::ItemContainer)); // gimmick_breakable_sack_06
        assert_eq!(container_class(1003953), Some(ContainerClass::ItemContainer)); // in_shops_hppotionwoodbox_01
        assert_eq!(container_class(1000155), Some(ContainerClass::ItemContainer)); // Background_Breakable_Wood_209
        assert_eq!(container_class(1004949), Some(ContainerClass::FurnitureDrop)); // gimmick_item_dropset_cabinet_01
        assert_eq!(container_class(1006434), Some(ContainerClass::FurnitureDrop)); // gimmick_item_dropset_armor_fabric_03
        assert_eq!(container_class(1000425), None); // treasurebox_small_01
        assert_eq!(container_class(1006143), None); // gimmick_in_dff_cabinet_27_parts01
        assert_eq!(container_class(1000022), None); // Collection_Prop_Trophy_0001
        assert_eq!(container_class(1000132), None); // pot_0013
        assert_eq!(container_class(1000285), None); // basecamp_warehouse_box_01_cover
        assert_eq!(container_class(1000838), None); // gimmick_treasurebox_padlock_safe_01
        assert_eq!(container_class(0), None);
        assert_eq!(container_class(u32::MAX), None);
    }

    #[test]
    fn names_are_the_log_vocabulary() {
        assert_eq!(ContainerClass::ItemContainer.name(), "item-container");
        assert_eq!(ContainerClass::FurnitureDrop.name(), "furniture-drop");
    }
}
